declare(strict_types=1);

namespace Gumslone\Vulns\Support;

/**
 * A representative base vector for every base score a CVSS version can
 * produce — generated by enumerating every base vector (729 for v2, 2 592
 * for v3.1, 186 624 for v4.0) through the package's own calculators and
 * keeping, per distinct score, the first vector in preference order:
 * network-reachable, low complexity, unprivileged, no interaction, highest
 * impact. That makes the pick deterministic and the "obvious" vector for the
 * common scores (9.8 → AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H, 7.5 → …/C:H/I:N/A:N).
 *
 * Used to backfill a vector when a source publishes only a score. A score
 * has many vectors, so an inferred vector is an approximation — records
 * carrying one flag it in VulnerabilityData::$inferredFields.
 */
final class CvssVectorTable
{
