    /**
     * A base vector that scores exactly $score under the given CVSS major
     * version, or — when no base vector produces that score (a temporal or
     * environmental score, a rounding artefact) — the vector with the nearest
     * score. Null only for an unknown version or an out-of-range score.
     */
    public static function vectorFor(int $version, float $score): ?string
    {
        $table = self::table($version);
        if ($table === [] || $score < 0.0 || $score > 10.0) {
            return null;
        }

        $key = number_format($score, 1, '.', '');
        if (isset($table[$key])) {
            return $table[$key];
        }

        $best = null;
        $bestDistance = PHP_FLOAT_MAX;
        foreach ($table as $tableScore => $vector) {
            $distance = round(abs((float) $tableScore - $score), 3);
            // Ties resolve upward: over-estimating severity is the safe side.
            if ($distance < $bestDistance || ($distance === $bestDistance && (float) $tableScore > $score)) {
                $bestDistance = $distance;
                $best = $vector;
            }
        }

        return $best;
    }

    /** Whether some base vector produces exactly this score (no approximation). */
    public static function isExact(int $version, float $score): bool
    {
        return isset(self::table($version)[number_format($score, 1, '.', '')]);
    }

    /** @return array<string, string> */
    private static function table(int $version): array
    {
        return match ($version) {
            2 => self::V2,
            3 => self::V3,
            4 => self::V4,
            default => [],
        };
    }
